theorem linearArrival_of_one_add_o {f e : ℝ → ℝ} {c σ : ℝ}
    (hf : ∀ τ, f τ = c * (τ - σ) * (1 + e τ)) (he : Tendsto e (𝓝[≠] σ) (𝓝 0)) :
    LinearArrival f c σ

theorem wMinus_of_firstVariation {Bcc Bcψ Bψc Bψψ p : ℝ}
    (hr : 0 < (Nmat Bcc Bcψ Bψc Bψψ p).trace) :
    TwinRate.wMinus (Nmat Bcc Bcψ Bψc Bψψ p).trace (Nmat Bcc Bcψ Bψc Bψψ p).det = 0

theorem E₂_eq (A : Matrix (Fin 4) (Fin 4) ℝ) (M : Matrix (Fin 2) (Fin 2) ℝ) {scl snc : ℝ}
    (hs : scl + snc = M.trace) (hp : scl * snc = M.det) :
    E₂ A M = PureZeros.e₂of (c₁ A) (c₂ A) scl snc

theorem contDiff_charpoly_coeff {A : E → Matrix (Fin 4) (Fin 4) ℝ}
    (h : ∀ i j, ContDiff ℝ k fun x => A x i j) (m : ℕ) (hm : m ≤ 4) :
    ContDiff ℝ k fun x => (A x).charpoly.coeff (4 - m)

theorem contDiff_E₁ {A : E → Matrix (Fin 4) (Fin 4) ℝ} {M : E → Matrix (Fin 2) (Fin 2) ℝ}
    (hA : ∀ i j, ContDiff ℝ k fun x => A x i j) (hM : ∀ i j, ContDiff ℝ k fun x => M x i j) :
    ContDiff ℝ k fun x => E₁ (A x) (M x)

theorem contDiff_E₂ {A : E → Matrix (Fin 4) (Fin 4) ℝ} {M : E → Matrix (Fin 2) (Fin 2) ℝ}
    (hA : ∀ i j, ContDiff ℝ k fun x => A x i j) (hM : ∀ i j, ContDiff ℝ k fun x => M x i j) :
    ContDiff ℝ k fun x => E₂ (A x) (M x)

theorem E₁_mirror {A : Matrix (Fin 4) (Fin 4) ℝ} {M : Matrix (Fin 2) (Fin 2) ℝ} {s : ℝ}
    (hM : M = s • (1 : Matrix (Fin 2) (Fin 2) ℝ))
    (hA : ∀ z, A.charpoly.eval z = (z - s) ^ 3 * (z + s)) : E₁ A M = 0

theorem E₂_mirror {A : Matrix (Fin 4) (Fin 4) ℝ} {M : Matrix (Fin 2) (Fin 2) ℝ} {s : ℝ}
    (hM : M = s • (1 : Matrix (Fin 2) (Fin 2) ℝ))
    (hA : ∀ z, A.charpoly.eval z = (z - s) ^ 3 * (z + s)) : E₂ A M = -s ^ 2

theorem charpoly_fin_two_factor {M : Matrix (Fin 2) (Fin 2) ℝ} {scl snc : ℝ}
    (hs : scl + snc = M.trace) (hp : scl * snc = M.det) :
    M.charpoly = (X - C scl) * (X - C snc)

theorem rootMultiplicity_zero_fin_two {M : Matrix (Fin 2) (Fin 2) ℝ} {scl snc : ℝ}
    (hne : scl ≠ snc) (hsnc : snc = 0) (hs : scl + snc = M.trace) (hp : scl * snc = M.det) :
    M.charpoly.rootMultiplicity 0 = 1

theorem contDiff_det_complex {E : Type*} [NormedAddCommGroup E] [NormedSpace ℝ E]
    {n : Type*} [Fintype n] [DecidableEq n] {m : WithTop ℕ∞} {A : E → Matrix n n ℂ}
    (h : ∀ i j, ContDiff ℝ m fun x => A x i j) : ContDiff ℝ m fun x => (A x).det
